class Solution:
    def simplifiedFractions(self, n: int) -> List[str]:
        from math import gcd
        seen, res = set(), []
        for b in range(2, n + 1):
            for a in range(1, b):
                g = gcd(a, b)
                key = (a // g, b // g)
                if key not in seen:
                    seen.add(key)
                    res.append(f"{key[0]}/{key[1]}")
        return res

