class Solution {
public:
    vector<string> simplifiedFractions(int n) {
        auto gcd = [](int x, int y) { while (y) { int t = x % y; x = y; y = t; } return x; };
        set<pair<int,int>> seen;
        vector<string> res;
        for (int b = 2; b <= n; ++b)
            for (int a = 1; a < b; ++a) {
                int g = gcd(a, b);
                pair<int,int> key = {a / g, b / g};
                if (!seen.count(key)) {
                    seen.insert(key);
                    res.push_back(to_string(key.first) + "/" + to_string(key.second));
                }
            }
        return res;
    }
};

