class Solution {
    public List<String> simplifiedFractions(int n) {
        Set<String> seen = new HashSet<>();
        List<String> res = new ArrayList<>();
        for (int b = 2; b <= n; b++)
            for (int a = 1; a < b; a++) {
                int g = gcd(a, b);
                String key = (a / g) + "/" + (b / g);
                if (seen.add(key)) res.add(key);
            }
        return res;
    }
    private int gcd(int x, int y) {
        return y == 0 ? x : gcd(y, x % y);
    }
}

